import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import { Menu, X, Sun, Moon, Github, Cpu, Book, Layout, Terminal } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import './AcidNavbar.css';

export interface NavItem {
    id: string;
    name: string;
    link: string;
    icon?: React.ReactNode;
}

export const AcidNavbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const [isDarkMode, setIsDarkMode] = useState(() => {
        return document.documentElement.getAttribute('data-theme') !== 'light';
    });
    const location = useLocation();

    useEffect(() => {
        document.documentElement.setAttribute('data-theme', isDarkMode ? 'dark' : 'light');
    }, [isDarkMode]);

    const navItems: NavItem[] = [
        { id: 'home', name: 'HOME', link: '/', icon: <Cpu size={14} /> },
        { id: 'docs', name: 'DOCUMENTATION', link: '/docs', icon: <Book size={14} /> },
        { id: 'components', name: 'LIBRARY', link: '/library', icon: <Layout size={14} /> },
    ];

    return (
        <header className="ac-navbar">
            <div className="ac-navbar-top-bar">
                <div className="ac-container ac-navbar-inner">
                    <div className="ac-navbar-left">
                        <Link to="/" className="ac-navbar-brand">
                            <Terminal className="text-brand" size={18} />
                            <span className="brand-text">ACID_UI <span className="version">v1.2.0</span></span>
                        </Link>
                    </div>

                    <nav className="ac-navbar-links desktop-only">
                        {navItems.map((item) => (
                            <Link
                                key={item.id}
                                to={item.link}
                                className={clsx('ac-navbar-link', location.pathname === item.link && 'active')}
                            >
                                <span className="link-icon">{item.icon}</span>
                                <span className="link-text">{item.name}</span>
                            </Link>
                        ))}
                    </nav>

                    <div className="ac-navbar-actions">
                        <button
                            className="ac-btn-icon"
                            onClick={() => setIsDarkMode(!isDarkMode)}
                            title="Toggle Theme"
                        >
                            {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
                        </button>

                        <a
                            href="https://github.com"
                            target="_blank"
                            rel="noreferrer"
                            className="ac-btn-icon desktop-only"
                            title="GitHub Repository"
                        >
                            <Github size={18} />
                        </a>

                        <button
                            className="ac-btn-icon mobile-only"
                            onClick={() => setIsOpen(!isOpen)}
                        >
                            {isOpen ? <X size={20} /> : <Menu size={20} />}
                        </button>
                    </div>
                </div>
            </div>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        className="ac-navbar-mobile-overlay"
                    >
                        <div className="ac-navbar-mobile-menu">
                            {navItems.map((item) => (
                                <Link
                                    key={item.id}
                                    to={item.link}
                                    className="ac-mobile-link"
                                    onClick={() => setIsOpen(false)}
                                >
                                    {item.icon}
                                    <span>{item.name}</span>
                                </Link>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </header>
    );
};

.ac-navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    background: var(--ac-bg);
    border-bottom: 2px solid var(--ac-border);
    font-family: var(--font-mono);
}

.ac-navbar-top-bar {
    height: 64px;
    display: flex;
    align-items: center;
}

.ac-navbar-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
}

.ac-navbar-brand {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    text-decoration: none;
    color: var(--ac-text-primary);
    font-weight: 700;
    letter-spacing: -0.02em;
}

.brand-text {
    font-size: 1.1rem;
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.version {
    font-size: 0.6rem;
    color: var(--ac-brand);
    border: 1px solid var(--ac-brand);
    padding: 0 4px;
    border-radius: 2px;
}

.ac-navbar-links {
    display: flex;
    align-items: center;
    gap: 2rem;
}

.ac-navbar-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    text-decoration: none;
    color: var(--ac-text-secondary);
    font-size: 0.75rem;
    font-weight: 500;
    letter-spacing: 0.05em;
    padding: 0.5rem 0;
    border-bottom: 2px solid transparent;
    transition: all 0.2s;
}

.ac-navbar-link:hover {
    color: var(--ac-text-primary);
}

.ac-navbar-link.active {
    color: var(--ac-brand);
    border-bottom-color: var(--ac-brand);
}

.ac-navbar-actions {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.ac-btn-icon {
    background: var(--ac-surface);
    border: 1px solid var(--ac-border);
    color: var(--ac-text-primary);
    padding: 0.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}

.ac-btn-icon:hover {
    background: var(--ac-border);
    border-color: var(--ac-text-secondary);
}

.ac-navbar-mobile-overlay {
    position: fixed;
    top: 64px;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(8px);
    z-index: 999;
}

.ac-navbar-mobile-menu {
    background: var(--ac-bg);
    border-bottom: 2px solid var(--ac-border);
    padding: 2rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.ac-mobile-link {
    display: flex;
    align-items: center;
    gap: 1rem;
    text-decoration: none;
    color: var(--ac-text-primary);
    font-size: 1rem;
    font-weight: 600;
}

@media (max-width: 768px) {
    .desktop-only {
        display: none;
    }
}

@media (min-width: 769px) {
    .mobile-only {
        display: none;
    }
}
